package com.shopsphere.filter;
import com.shopsphere.model.User; import jakarta.servlet.*; import jakarta.servlet.http.*; import jakarta.servlet.annotation.*; import java.io.IOException;
@WebFilter({"/cart","/checkout","/orders","/wishlist","/profile"}) public class AuthenticationFilter implements Filter {public void doFilter(ServletRequest rq,ServletResponse rs,FilterChain chain)throws IOException,ServletException{HttpServletRequest q=(HttpServletRequest)rq;HttpServletResponse p=(HttpServletResponse)rs;HttpSession s=q.getSession(false);User u=s==null?null:(User)s.getAttribute("user");if(u==null){p.sendRedirect(q.getContextPath()+"/login?next="+java.net.URLEncoder.encode(q.getRequestURI().substring(q.getContextPath().length()),java.nio.charset.StandardCharsets.UTF_8));return;}chain.doFilter(rq,rs);}}
